shader:
// Luma Dissolve - B grows in through the outgoing shot's accents first, as a soft graded dissolve: a mostly dark shot
// leaves through its highlights (highlights -> shadows), a mostly light shot through its darks (shadows -> highlights),
// so the old accent always goes first and the new shot's accents land last - the same order in both directions.
// The direction is a soft majority vote of the 9 stats-grid samples of A (light share 25 -> 75 %: continuous, no flip
// inside a cut); a grey shot in between gets an even dissolve. `invert` = reverse that order.
// Key = tone of the outgoing picture (A leads: 0.8 / 0.2 with B regionally, 0.9 / 0.1 at the pixel), mixed 85 / 15
// from two scales:
//   regional (85 %) - a 3x3 quadratic B-spline over a coarse lattice of key samples (cell = 6 % of the height): smooth
//   and deterministic, so whole heads / bodies go together (no sticker rims, no ring copies, no speckle);
//   pixel (15 %) - the picture's own tone, so the front still follows the image, while eyes, brows and lips stay with
//   their skin (peak gap ~0.16 of the fade on the bench's talking head, either order: no floating or punched-out
//   features); plus a faint drifting fbm.
// Every pixel's key is turned into a rank inside the pair's key distribution (3x3 grid of both shots, weighted by how
// much they differ there, separate spreads above / below the mean) - the reveal pace is the same for any pair.
// Each pixel fades over its own window whose start follows its rank. Tuned for a fast 0.47 s cut (14 frames): the
// leading (bright) side reaches further ahead and the lights start on the first frame, so the highlights-first order
// still reads. By design a bright face over a dark next shot goes about 2 frames (~70 ms) before its darker body, and
// the wall right around a head trails the open wall about as long. The lagging (shadow) side is held close to the
// overall progress and a lead / lag clamp eases every ghost out by 78 % (80 % with Shadows first, which also keeps 20 %
// pixel tone, so its reveal stays as even as before). Around the cut: light soft focus (Orton), chroma restore where
// the shots overlap (no silver mud), a gentle bloom on the front, dither.
// Taps: 2 centre + 18 stats grid + 18 lattice + 10 soft-focus = 48.

// Hoskins hash12 on integer coordinates (stable at full-res exports)
float ldHash(vec2 q) {
    vec3 p3 = fract(vec3(q.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

float ldNoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    float a = ldHash(i);
    float b = ldHash(i + vec2(1.0, 0.0));
    float c = ldHash(i + vec2(0.0, 1.0));
    float d = ldHash(i + vec2(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float ldFbm(vec2 p) {
    float s = 0.0;
    float a = 0.5;
    float n = 0.0;
    const int OCT = 2;
    for (int i = 0; i < OCT; i++) {
        s += a * ldNoise(p);
        n += a;
        p = p * 2.03 + vec2(17.1, 9.7);
        a *= 0.5;
    }
    return s / n;
}

// tone of the key: mostly display luma, part exposure stops (lamps and lit faces lead, darks still separate)
float ldTone(float l) {
    float stops = clamp((log2(pow(max(l, 0.0), 2.2) + 0.003) + 7.5) / 7.5, 0.0, 1.0);
    return mix(l, stops, 0.4);
}

// key luma: the outgoing picture leads, so the incoming shot's lamps never punch through faces
float ldKeyL(vec3 a, vec3 b) { return mix(luma(a), luma(b), 0.20); }

// grid sample of the key: (tone, weight = how much the shots differ there, light vote of the outgoing shot)
vec3 ldGrid(vec2 g) {
    vec3 a = getA(g).rgb;
    vec3 b = getB(g).rgb;
    return vec3(ldTone(ldKeyL(a, b)), 0.05 + length(a - b), smoothstep(0.35, 0.65, luma(a)));
}

// weighted squared deviation above / below the centre
vec2 ldSemi(vec3 g, float mu) {
    float dv = g.x - mu;
    return vec2(step(0.0, dv), step(dv, 0.0)) * dv * dv * g.y;
}

// key luma of one lattice point (screen space -> each shot's pushed frame)
float ldLat(vec2 u, vec2 sc) {
    vec2 c = vec2(0.5);
    return ldKeyL(getA((u - c) / sc.x + c).rgb, getB((u - c) / sc.y + c).rgb);
}

vec4 transition(vec2 uv) {
    float p = clamp(progress, 0.0, 1.0);
    float ps = p * p * (3.0 - 2.0 * p);
    float env = max(sin(3.14159265 * p), 0.0);

    // gentle push: A drifts in as it leaves, B settles from slightly closer
    vec2 ctr = vec2(0.5);
    vec2 uvA = (uv - ctr) / (1.0 + 0.035 * ps) + ctr;
    vec2 uvB = (uv - ctr) / (1.0 + 0.035 * (1.0 - ps)) + ctr;

    vec3 a0 = getA(uvA).rgb;
    vec3 b0 = getB(uvB).rgb;

    // per-pair key statistics: 3x3 grid on both shots (same for every pixel), weighted by how much the two shots
    // differ there - the pace is equalised over the part of the picture that visibly changes
    vec3 g0 = ldGrid(vec2(0.17, 0.17));
    vec3 g1 = ldGrid(vec2(0.50, 0.17));
    vec3 g2 = ldGrid(vec2(0.83, 0.17));
    vec3 g3 = ldGrid(vec2(0.17, 0.50));
    vec3 g4 = ldGrid(vec2(0.50, 0.50));
    vec3 g5 = ldGrid(vec2(0.83, 0.50));
    vec3 g6 = ldGrid(vec2(0.17, 0.83));
    vec3 g7 = ldGrid(vec2(0.50, 0.83));
    vec3 g8 = ldGrid(vec2(0.83, 0.83));
    float gw = g0.y + g1.y + g2.y + g3.y + g4.y + g5.y + g6.y + g7.y + g8.y;
    float mu = (g0.x * g0.y + g1.x * g1.y + g2.x * g2.y + g3.x * g3.y + g4.x * g4.y
              + g5.x * g5.y + g6.x * g6.y + g7.x * g7.y + g8.x * g8.y) / gw;
    // separate spreads above / below the centre (key histograms are skewed: highlights pile up near white)
    vec2 sd = ldSemi(g0, mu) + ldSemi(g1, mu) + ldSemi(g2, mu) + ldSemi(g3, mu) + ldSemi(g4, mu)
            + ldSemi(g5, mu) + ldSemi(g6, mu) + ldSemi(g7, mu) + ldSemi(g8, mu);
    // floor keeps flat / low-contrast pairs from turning into a hard graphic key
    float sigUp = max(sqrt(2.0 * sd.x / gw) * 0.90, 0.07);
    float sigDn = max(sqrt(2.0 * sd.y / gw) * 0.90, 0.07);
    // order: a mostly light outgoing shot leaves through its darks (its accents), a mostly dark one through its lights
    float vote = (g0.z + g1.z + g2.z + g3.z + g4.z + g5.z + g6.z + g7.z + g8.z) / 9.0;
    float inv = abs(step(0.5, invert) - smoothstep(0.25, 0.75, vote));

    // regional key luma: a coarse lattice of key samples (screen space, cell = 6 % of the height), blended with a
    // quadratic B-spline over the 3x3 nearest points - a smooth, near-round "virtual mip". Deterministic and continuous:
    // no ring copies (sparse fixed discs) and no sand speckle (per-pixel jitter) in the timing field.
    vec2 cell = vec2(0.06 / ratio, 0.06);
    vec2 q = uv / cell;
    vec2 ic = floor(q);
    vec2 t = q - ic - 0.5;
    vec2 w0 = 0.5 * (0.5 - t) * (0.5 - t);
    vec2 w2 = 0.5 * (0.5 + t) * (0.5 + t);
    vec2 w1 = 1.0 - w0 - w2;
    vec2 uc = (ic + 0.5) * cell;
    vec2 sc = vec2(1.0 + 0.035 * ps, 1.0 + 0.035 * (1.0 - ps));
    vec3 r0 = vec3(ldLat(uc + vec2(-cell.x, -cell.y), sc), ldLat(uc + vec2(0.0, -cell.y), sc), ldLat(uc + vec2(cell.x, -cell.y), sc));
    vec3 r1 = vec3(ldLat(uc + vec2(-cell.x, 0.0), sc), ldLat(uc, sc), ldLat(uc + vec2(cell.x, 0.0), sc));
    vec3 r2 = vec3(ldLat(uc + vec2(-cell.x, cell.y), sc), ldLat(uc + vec2(0.0, cell.y), sc), ldLat(uc + vec2(cell.x, cell.y), sc));
    vec3 wx = vec3(w0.x, w1.x, w2.x);
    float lR = w0.y * dot(r0, wx) + w1.y * dot(r1, wx) + w2.y * dot(r2, wx);

    // soft-focus colours: small disc (1 % of the height), rotated per pixel so it never steps into copies
    const int NS = 5;
    float RS = 0.010;
    float rot = ldHash(floor(uv * resolution)) * 6.2831853;
    vec3 sa = a0 * 0.6;
    vec3 sb = b0 * 0.6;
    float sws = 0.6;
    for (int i = 0; i < NS; i++) {
        float fi = float(i);
        float r = RS * sqrt((fi + 0.5) / float(NS));
        float ang = fi * 2.39996323 + rot;
        vec2 off = vec2(cos(ang) / ratio, sin(ang)) * r;
        sa += getA(uvA + off).rgb;
        sb += getB(uvB + off).rgb;
        sws += 1.0;
    }
    sa /= sws;
    sb /= sws;

    float n = ldFbm(uv * vec2(ratio, 1.0) * 4.5 + vec2(time * 0.22, -time * 0.1)) - 0.5;
    float kR = ldTone(lR);
    float kD = ldTone(mix(luma(a0), luma(b0), 0.10));
    // mostly regional: enough pixel detail for the front to follow the picture, little enough that dark features
    // (eyes, brows, open mouth, lips) stay with their skin even with the fast cut's stronger bright lead. Shadows first
    // keeps a little more detail (20 %): its order reads from the darks' own tone and the reveal spreads more evenly
    float k = kR + (kD - kR) * mix(0.15, 0.20, inv) + n * 0.08;
    // rank of the pixel inside the pair's key distribution (logistic ~ normal CDF): equalised, so the reveal pace
    // is the same for every pair; bright first (or shadows first)
    float zk = k - mu;
    float zg = kR + n * 0.08 - mu;
    float u = 1.0 / (1.0 + exp(-1.702 * zk / (zk > 0.0 ? sigUp : sigDn)));
    float ug = 1.0 / (1.0 + exp(-1.702 * zg / (zg > 0.0 ? sigUp : sigDn)));
    float d = mix(1.0 - u, u, inv);
    float dg = mix(1.0 - ug, ug, inv);

    // each pixel fades over its own window; the window's start follows its rank (soft S overall, centred on the anchor)
    float w = 0.2 + softness * 0.5;
    float hs = max(0.58 - w, 0.17);
    // leading is the effect, lagging is a ghost: the early (bright) side reaches further ahead so the order reads even
    // in a 14-frame cut, the late (shadow) side keeps closer to the overall progress
    float dd = 2.0 * d - 1.0;
    float c = 0.515 + hs * dd * (dd > 0.0 ? 0.55 : 1.45);
    float m = smoothstep(c - w, c + w, p);
    // no pixel may lead or lag the overall progress too far: the lights start on the first frame, the last shadows
    // ease out (soft landing, no snap) and are gone by 78 % (80 % with Shadows first, whose lagging lights land a touch
    // gentler)
    float mLo = smoothstep(0.36, mix(0.78, 0.80, inv), p);
    float mHi = smoothstep(0.0, 0.42, p);
    m = clamp(m, mLo, mHi);

    vec3 col = mix(a0, b0, m);

    // Orton-style soft focus around the cut: no frame shows two razor-sharp pictures stacked
    vec3 blur = mix(sa, sb, m);
    float gh = 4.0 * m * (1.0 - m);
    col = mix(col, blur, 0.35 * env * env);
    // a blend of two pictures loses chroma (the silver / grey-mud look) - give part of it back where they overlap
    float lc = luma(col);
    col = max(vec3(lc) + (col - vec3(lc)) * (1.0 + 0.30 * gh), vec3(0.0));

    // bloom on the reveal front (same timing as the reveal), coloured by the blurred picture; highlight bloom peaks at
    // the hidden cut
    float ddg = 2.0 * dg - 1.0;
    float cg = 0.515 + hs * ddg * (ddg > 0.0 ? 0.55 : 1.45);
    float wg = w * 1.6 + 0.04;
    float mg = smoothstep(cg - wg, cg + wg, p);
    float band = 4.0 * mg * (1.0 - mg) * env;
    vec3 glowCol = blur * vec3(1.0, 0.97, 0.92);
    vec3 bloom = glowCol * band * 0.15;
    bloom += max(blur - vec3(0.82), vec3(0.0)) * 0.9 * env * env;
    bloom = clamp(bloom * glow, 0.0, 1.0);
    col = 1.0 - (1.0 - col) * (1.0 - bloom);

    // dither while live (smooth glow, no banding)
    vec2 qd = floor(uv * resolution) + floor(time * 30.0) * vec2(7.0, 13.0);
    col += (ldHash(qd) - 0.5) * (1.5 / 255.0) * env;

    return vec4(clamp(col, 0.0, 1.0), 1.0);
}
